  async function load(){setLoadState("loading");try{const loaded=await loadDashboard(fetch,auth,{date:today(),timeZone:zone()});commandController.setIdentity(loaded.identity.issuer,loaded.identity.subjectId,loaded.identity.clientId);setIdentityKey(`${loaded.identity.issuer}:${loaded.identity.subjectId}:${loaded.identity.clientId}`);epochHeader=loaded.epochHeader;setData(loaded.data);setTodayData(loaded.today);setTimeline(loaded.timeline?.items??[]);setTimelineCursor(loaded.timeline?.next_cursor??null);setHealthWorkspace(loaded.health);setCapabilities(loaded.capabilities);setFields(current=>!loaded.capabilities.includes("money.set_budget")&&loaded.capabilities.includes("health.set_plan")&&current.planKind==="budget"?{...current,planKind:"goal"}:current);const labels:Record<DashboardDomain|"today"|"timeline",string>={meals:"饮食",money:"账目",health:"健康",travel:"旅行",library:"资料",today:"今日摘要",timeline:"时间线"},messages=(Object.entries(loaded.errors) as [DashboardDomain|"today"|"timeline",string][]).map(([domain,message])=>`${labels[domain]}：${message}`);setReadError(messages.length?messages.join("；"):undefined);setLoadState(messages.length||!loaded.today?"partial":"ready");}catch(caught){setReadError(caught instanceof Error?caught.message:"读取失败");setLoadState("error");}}
