  useEffect(()=>{if(!threadId)return;void fetch(`/api/threads/${threadId}/messages`,{headers:auth}).then(async response=>{if(!response.ok)throw new Error();const body=await response.json() as {items:{role:"user"|"assistant";content:string}[]};setTurns(body.items.map(item=>({role:item.role,text:item.content})));}).catch(()=>{try{persistentStorage.removeItem?.(threadStorageKey)}catch{}setThreadId(undefined);});},[threadId,threadStorageKey]);
